window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["授受表現"]={
"_note": "03. 授受表現 — mỗi mục một dòng. LEVEL: n5 → n1 = cấp độ JLPT từ sơ cấp (n5) đến cao cấp (n1). THỨ TỰ: các nhóm xếp n5, n4, n3, n2, n1, không trộn lẫn; trong mỗi nhóm giữ nguyên thứ tự gốc. ĐỊNH DẠNG MỖI TỪ: word, reading, meaning, note, example, example_reading, example_meaning, level, hanviet (tuỳ chọn). TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: n5 13, n4 18, n3 27, n2 24, n1 18; tổng 100 mục từ vựng + 25 mẫu ngữ pháp (pattern, usage, example, example_reading, example_meaning).",
"id": "3. 授受表現",
"title": "授受表現",
"icon": "🎁",
"category": "ref",
"vocab": [
{"word":"あげる","reading":"あげる","meaning":"cho, tặng (tôi / người ngang hàng cho người khác)","note":"TRỢ TỪ: AがBにCをあげる ▸ が = người cho (chủ ngữ) ▸ に = người nhận (BẮT BUỘC dùng に, không dùng から) ▸ を = vật được cho. Vật có thể lên trước làm chủ đề bằng は: 本はBにあげた. Người nhận là 'tôi' thì KHÔNG dùng あげる (dùng くれる).","antonym":"もらう: nhận","example":"私は妹に誕生日プレゼントをあげました。","example_reading":"わたしはいもうとにたんじょうびぷれぜんとをあげました。","example_meaning":"Tôi đã tặng em gái quà sinh nhật.","level":"n5"},
{"word":"もらう","reading":"もらう","meaning":"nhận, được cho","antonym":"あげる: cho / やる: cho","note":"TRỢ TỪ: BがAにCをもらう ▸ が/は = người nhận (chủ ngữ) ▸ に hoặc から = người cho ▸ を = vật nhận. に và から đều đúng; khi người cho là tổ chức/nơi chốn (会社、学校、市役所) thì ưu tiên から.","example":"私は先輩に（から）アドバイスをもらいました。","example_reading":"わたしはせんぱいに（から）あどばいすをもらいました。","example_meaning":"Tôi đã nhận được lời khuyên từ đàn anh.","level":"n5"},
{"word":"くれる","reading":"くれる","meaning":"(người khác) cho tôi / phía tôi","antonym":"あげる: (mình) cho người khác / もらう: nhận","note":"TRỢ TỪ: AがBにCをくれる ▸ が = người cho (chủ ngữ) ▸ に = người nhận (phải là tôi/người thân của tôi, thường lược bỏ) ▸ を = vật. Chia lịch sự: くれます／くれました.","example":"友達が私にお土産を買ってきてくれました。","example_reading":"ともだちがわたしにおみやげをかってきてくれました。","example_meaning":"Bạn đã mua quà lưu niệm về cho tôi.","level":"n5"},
{"word":"貸す","reading":"かす","meaning":"cho mượn, cho vay","hanviet":"thải","note":"TRỢ TỪ: AがBにCを貸す ▸ に = người mượn ▸ を = vật. Đối lập: 借りる. Lưu ý: に chỉ người nhận, không dùng から.","antonym":"借りる（かりる）: mượn, thuê","antonym_hanviet":"tá","example":"友達にノートを貸しました。","example_reading":"ともだちにのーとをかしました。","example_meaning":"Tôi cho bạn mượn vở.","level":"n5"},
{"word":"借りる","reading":"かりる","meaning":"mượn, vay","hanviet":"tá","note":"TRỢ TỪ: AがBにCを借りる ▸ に hoặc から = người cho mượn ▸ を = vật. Giống もらう: に/から đều đúng, から hợp khi là tổ chức/ngân hàng.","antonym":"貸す（かす）: cho mượn, cho thuê / 返す（かえす）: trả lại","antonym_hanviet":"thải / phản","example":"図書館から本を借りました。","example_reading":"としょかんからほんをかりました。","example_meaning":"Tôi đã mượn sách ở thư viện.","level":"n5"},
{"word":"返す","reading":"かえす","meaning":"trả lại","hanviet":"phản","note":"TRỢ TỪ: AがBにCを返す ▸ に = người nhận lại ▸ を = vật. Hay đi với 借りた物: 借りた本を返す.","antonym":"借りる（かりる）: mượn / 盗む（ぬすむ）: ăn cắp","antonym_hanviet":"tá / đạo","example":"借りた本を図書館に返してきます。","example_reading":"かりたほんをとしょかんにかえしてきます。","example_meaning":"Tôi đi trả sách mượn cho thư viện.","level":"n5"},
{"word":"教える","reading":"おしえる","meaning":"dạy, chỉ cho biết","hanviet":"giáo","note":"TRỢ TỪ: AがBにCを教える ▸ に = người được dạy ▸ を = nội dung/môn học. Đối lập: 習う／教わる (cặp 'cho-nhận' của tri thức). Không dùng から cho người được dạy.","antonym":"習う（ならう）: học / 教わる（おそわる）: được dạy / 学ぶ（まなぶ）: học","antonym_hanviet":"tập / giáo / học","example":"兄が弟に数学を教えています。","example_reading":"あにがおとうとにすうがくをおしえています。","example_meaning":"Anh trai đang dạy toán cho em trai.","level":"n5"},
{"word":"習う","reading":"ならう","meaning":"học (từ ai), theo học","hanviet":"tập","note":"TRỢ TỪ: AがBにCを習う ▸ に hoặc から = người dạy ▸ を = nội dung. Giống もらう về cách dùng に/から (cách nói 'nhận kiến thức'). Dạng khác: 教わる.","antonym":"教える（おしえる）: dạy","antonym_hanviet":"giáo","example":"私は先生にピアノを習っています。","example_reading":"わたしはせんせいにぴあのをならっています。","example_meaning":"Tôi đang học piano với cô giáo.","level":"n5"},
{"word":"プレゼント","reading":"ぷれぜんと","meaning":"quà tặng","note":"Danh từ. Mẫu: Bにプレゼントをあげる／Aからプレゼントをもらう／Aがプレゼントをくれる. Khác お土産 (quà mang về sau chuyến đi) và お祝い (quà mừng). Gắn với dịp: 誕生日プレゼント、クリスマスプレゼント.","example":"誕生日に友達からプレゼントをもらいました。","example_reading":"たんじょうびにともだちからぷれぜんとをもらいました。","example_meaning":"Vào sinh nhật, tôi đã nhận quà từ bạn.","level":"n5"},
{"word":"見せる","reading":"みせる","meaning":"cho xem, đưa xem","hanviet":"kiến","note":"TRỢ TỪ: AがBにCを見せる ▸ に = người xem ▸ を = vật. Thuộc nhóm CHO nên người nhận dùng に. Ghép: 見せてあげる／見せてくれる／見せてもらう. Lịch sự: お見せする (khiêm nhường), 見せていただく.","antonym":"隠す（かくす）: giấu","antonym_hanviet":"ẩn","example":"友達に旅行の写真を見せてもらいました。","example_reading":"ともだちにりょこうのしゃしんをみせてもらいました。","example_meaning":"Tôi được bạn cho xem ảnh du lịch.","level":"n5"},
{"word":"出す","reading":"だす","meaning":"gửi (thư), nộp, đưa ra","hanviet":"xuất","note":"TRỢ TỪ: AがBにCを出す ▸ に = người nhận ▸ を = thư/bưu thiếp/bài. Trong chủ đề này: 手紙／はがきを出す = bỏ thư gửi đi (nhấn hành động gửi). Nghĩa khác: 宿題を出す (nộp/giao bài), お金を出す (bỏ tiền ra).","antonym":"入れる（いれる）: cho vào","antonym_hanviet":"nhập","example":"母にはがきを出しました。","example_reading":"ははにはがきをだしました。","example_meaning":"Tôi đã gửi bưu thiếp cho mẹ.","level":"n5"},
{"word":"買う","reading":"かう","meaning":"mua","hanviet":"mãi","antonym":"売る（うる）: bán / 我慢する（がまんする）: nhịn mua","antonym_hanviet":"mại / ngã mạn","note":"TRỢ TỪ: Bに Cを買ってあげる／買ってくれる／買ってもらう ▸ に = người được mua cho (hoặc người mua hộ) ▸ を = vật. Nơi mua dùng で／から (店で買う、人から買う). Hay đi cùng ～てくる: 買ってきてくれる (mua về giúp).","example":"母が私に新しい自転車を買ってくれました。","example_reading":"ははがわたしにあたらしいじてんしゃをかってくれました。","example_meaning":"Mẹ đã mua cho tôi chiếc xe đạp mới.","level":"n5"},
{"word":"作る","reading":"つくる","meaning":"làm, nấu, chế tạo","hanviet":"tác","note":"TRỢ TỪ: Bに Cを作ってあげる／作ってくれる／作ってもらう ▸ に = người hưởng lợi/người làm hộ ▸ を = vật. Khiêm nhường khi làm cho người trên: お作りする; nhờ người trên: お作りいただく.","antonym":"壊す（こわす）: phá","antonym_hanviet":"hoại","example":"彼女は私にお弁当を作ってくれました。","example_reading":"かのじょはわたしにおべんとうをつくってくれました。","example_meaning":"Cô ấy đã làm cơm hộp cho tôi.","level":"n5"},
{"word":"やる","reading":"やる","meaning":"cho (người dưới, thú vật, cây cối)","antonym":"もらう: nhận","note":"TRỢ TỪ: AがBにCをやる ▸ に = đối tượng nhận (con vật, cây, trẻ nhỏ) ▸ を = thứ cho (thức ăn, nước). Giống あげる về trợ từ, chỉ khác sắc thái bình dân/nam tính. Không dùng cho người trên.","example":"毎朝、猫にえさをやります。","example_reading":"まいあさ、ねこにえさをやります。","example_meaning":"Mỗi sáng tôi cho mèo ăn.","level":"n4"},
{"word":"いただく","reading":"いただく","meaning":"nhận (khiêm nhường của もらう); xin phép ăn/uống","note":"TRỢ TỪ: 私がAさんにCをいただく ▸ に/から = người cho (bề trên) ▸ を = vật nhận. Chia: いただきます／いただきました／いただけます (khả năng). Dùng cả khi ăn: いただきます.","antonym":"差し上げる（さしあげる）: biếu (khiêm nhường)","antonym_hanviet":"sai thượng","example":"先生から貴重な資料をいただきました。","example_reading":"せんせいからきちょうなしりょうをいただきました。","example_meaning":"Em đã được thầy cho tài liệu quý.","level":"n4"},
{"word":"くださる","reading":"くださる","meaning":"(bề trên) cho tôi / phía tôi (tôn kính của くれる)","antonym":"いただく: (khiêm nhường) nhận từ bề trên","note":"TRỢ TỪ: 先生／部長がCをくださる ▸ が = người cho (bề trên) ▸ に = người nhận (tôi, thường lược) ▸ を = vật. Chia bất quy tắc: くださいます, くださいました, くださって.","example":"部長が私たちに励ましの言葉をくださいました。","example_reading":"ぶちょうがわたしたちにはげましのことばをくださいました。","example_meaning":"Trưởng phòng đã động viên chúng tôi bằng những lời tốt đẹp.","level":"n4"},
{"word":"プレゼントする","reading":"プレゼントする","meaning":"tặng quà","note":"TRỢ TỪ: AがBにCをプレゼントする ▸ に = người nhận ▸ を = quà. Giống あげる nhưng chỉ dùng cho quà tặng, không dùng cho 'cho' chung chung.","example":"彼女にネックレスをプレゼントするつもりです。","example_reading":"かのじょにねっくれすをぷれぜんとするつもりです。","example_meaning":"Tôi định tặng bạn gái một sợi dây chuyền.","level":"n4"},
{"word":"渡す","reading":"わたす","meaning":"đưa cho, trao","hanviet":"độ","note":"TRỢ TỪ: AがBにCを渡す ▸ に = người nhận ▸ を = vật. Chỉ hành vi trao tay, không có sắc thái tặng quà. Cũng dùng: 橋を渡す (bắc cầu), 川を渡す.","antonym":"受け取る（うけとる）: nhận lấy","antonym_hanviet":"thụ thủ","example":"受付で書類を渡してください。","example_reading":"うけつけでしょるいをわたしてください。","example_meaning":"Hãy đưa giấy tờ ở quầy lễ tân.","level":"n4"},
{"word":"送る","reading":"おくる","meaning":"gửi, tiễn","hanviet":"tống","note":"TRỢ TỪ: AがBにCを送る ▸ に = người nhận/nơi nhận ▸ を = vật gửi ▸ で = phương tiện (郵便で、メールで). Gửi từ đâu dùng から: 東京から送る. Cùng chữ 送 nhưng 'gửi hàng' ≠ 'tiễn người'.","antonym":"受け取る（うけとる）: nhận","antonym_hanviet":"thụ thủ","example":"母にメールで写真を送りました。","example_reading":"ははにめーるでしゃしんをおくりました。","example_meaning":"Tôi đã gửi ảnh cho mẹ qua email.","level":"n4"},
{"word":"届ける","reading":"とどける","meaning":"chuyển tới, giao tận nơi","hanviet":"giới","antonym":"受け取る（うけとる）: nhận","antonym_hanviet":"thụ thủ","note":"TRỢ TỪ: AがBにCを届ける ▸ に = nơi/người nhận ▸ を = vật. Nhấn mạnh việc đem đến tận nơi. Tự động từ tương ứng: 届く (CがBに届く = Cđến B).","example":"忘れ物を受付に届けました。","example_reading":"わすれものをうけつけにとどけました。","example_meaning":"Tôi đã mang đồ bỏ quên tới quầy lễ tân.","level":"n4"},
{"word":"分ける","reading":"わける","meaning":"chia, chia sẻ phần cho","hanviet":"phân","antonym":"集める（あつめる）: gom lại / 合わせる（あわせる）: gộp lại","antonym_hanviet":"tập / hợp","note":"TRỢ TỪ: AがBにCを分ける ▸ に = người được chia ▸ を = vật. Hay dùng dạng ～を分けてあげる／分けてくれる／分けてもらう. Đừng nhầm với 'chia thành': AをBに分ける (に = kết quả chia, không phải người nhận).","example":"お菓子をたくさんもらったので、同僚にも分けてあげました。","example_reading":"おかしをたくさんもらったので、どうりょうにもわけてあげました。","example_meaning":"Vì được cho nhiều bánh kẹo nên tôi cũng chia cho đồng nghiệp.","level":"n4"},
{"word":"お土産","reading":"おみやげ","meaning":"quà (mua mang về khi đi xa), quà lưu niệm","hanviet":"thổ sản","note":"Danh từ, hay đi với: お土産を買う／買ってくる／あげる／もらう／くれる／配る. Khác プレゼント (quà nhân dịp sinh nhật, kỷ niệm): お土産 là quà mang về sau chuyến đi, thường cho gia đình, đồng nghiệp. Quà mang khi đến thăm nhà người khác: 手土産.","example":"北海道のお土産を同僚に配りました。","example_reading":"ほっかいどうのおみやげをどうりょうにくばりました。","example_meaning":"Tôi đã phát quà Hokkaido cho đồng nghiệp.","level":"n4"},
{"word":"払う","reading":"はらう","meaning":"trả (tiền)","hanviet":"phất","note":"TRỢ TỪ: AがBにCを払う ▸ に = người nhận tiền ▸ を = tiền/chi phí. Cụm: お金を払う、料金を払う. Ghép: 払ってあげる／払ってくれる／払ってもらう (≈ おごってもらう). Trang trọng hơn: 支払う.","antonym":"受け取る（うけとる）: nhận","antonym_hanviet":"thụ thủ","example":"昨日の食事代は、先輩が払ってくれました。","example_reading":"きのうのしょくじだいは、せんぱいがはらってくれました。","example_meaning":"Tiền ăn hôm qua anh khóa trên đã trả hộ tôi.","level":"n4"},
{"word":"頼む","reading":"たのむ","meaning":"nhờ, nhờ vả; đặt (món)","hanviet":"lại","antonym":"断る（ことわる）: từ chối / 引き受ける（ひきうける）: nhận lời","antonym_hanviet":"đoạn / dẫn thụ","note":"TRỢ TỪ: AがBにCを頼む ▸ に = người được nhờ ▸ を = việc/vật. Mẫu: Bに～てほしいと頼む／～ように頼む. Là bước đầu dẫn tới ～てもらう (nhờ rồi được làm giúp). Lịch sự: お願いする (khiêm nhường). Bị nhờ: 頼まれる.","example":"友達に引っ越しの手伝いを頼みました。","example_reading":"ともだちにひっこしのてつだいをたのみました。","example_meaning":"Tôi đã nhờ bạn giúp chuyển nhà.","level":"n4"},
{"word":"手伝う","reading":"てつだう","meaning":"giúp, giúp đỡ","hanviet":"thủ truyền","note":"TRỢ TỪ: AがBを手伝う／AがBの仕事を手伝う ▸ người được giúp đi với を hoặc の, KHÔNG dùng に cho người được giúp. Ghép: 手伝ってあげる／手伝ってくれる／手伝ってもらう (khi ghép ～てもらう thì người làm giúp mới đi với に: 友達に手伝ってもらう).","example":"弟の宿題を手伝ってあげました。","example_reading":"おとうとのしゅくだいをてつだってあげました。","example_meaning":"Tôi đã giúp em trai làm bài tập.","level":"n4"},
{"word":"紹介する","reading":"しょうかいする","meaning":"giới thiệu","hanviet":"thiệu giới","note":"TRỢ TỪ: AがBにCを紹介する ▸ に = người được giới thiệu cho ▸ を = người/vật được giới thiệu. Ghép: 紹介してあげる／紹介してくれる／紹介してもらう. Lịch sự: ご紹介いただく.","example":"先輩が私に新しい仕事を紹介してくれました。","example_reading":"せんぱいがわたしにあたらしいしごとをしょうかいしてくれました。","example_meaning":"Đàn anh đã giới thiệu cho tôi một công việc mới.","level":"n4"},
{"word":"招待する","reading":"しょうたいする","meaning":"mời (đến dự)","hanviet":"chiêu đãi","note":"TRỢ TỪ: AがBをCに招待する ▸ を = người được mời ▸ に = sự kiện/nơi. Chú ý: người được mời đi với を, KHÔNG phải に. Ghép: 招待してもらう／招待される; lịch sự: ご招待いただく.","example":"友達が結婚式に私を招待してくれました。","example_reading":"ともだちがけっこんしきにわたしをしょうたいしてくれました。","example_meaning":"Bạn đã mời tôi đến đám cưới.","level":"n4"},
{"word":"知らせる","reading":"しらせる","meaning":"báo, thông báo","hanviet":"tri","note":"TRỢ TỪ: AがBにCを知らせる ▸ に = người nhận tin ▸ を = tin tức. Danh từ: お知らせ (thông báo). Ghép: 知らせてくれる／知らせてもらう.","example":"合格したら、すぐに家族に知らせます。","example_reading":"ごうかくしたら、すぐにかぞくにしらせます。","example_meaning":"Nếu đỗ, tôi sẽ báo ngay cho gia đình.","level":"n4"},
{"word":"お願いする","reading":"おねがいする","meaning":"nhờ, xin (khiêm nhường của 頼む)","hanviet":"nguyện","antonym":"お断りする（おことわりする）: từ chối (khiêm nhường)","antonym_hanviet":"đoạn","note":"TRỢ TỪ: AがBにCをお願いする ▸ に = người được nhờ ▸ を = việc. お願いします = 'xin nhờ'. Mẫu: ～をお願いします (đề nghị dịch vụ), ～をお願いできますか (nhờ lịch sự).","example":"部長に資料の確認をお願いしました。","example_reading":"ぶちょうにしりょうのかくにんをおねがいしました。","example_meaning":"Tôi đã nhờ trưởng phòng xem lại tài liệu.","level":"n4"},
{"word":"連れていく","reading":"つれていく","meaning":"dẫn đi, đưa đi cùng","hanviet":"liên","antonym":"連れてくる（つれてくる）: dẫn đến","antonym_hanviet":"liên","note":"TRỢ TỪ: AがBをCに連れていく ▸ を = người được dẫn ▸ に = nơi đến. Ghép: 連れていってあげる／連れていってくれる／連れていってもらう (người dẫn = chủ ngữ hoặc に). Chiều ngược (về phía người nói): 連れてくる.","example":"先輩が私を新しいレストランに連れていってくれました。","example_reading":"せんぱいがわたしをあたらしいれすとらんにつれていってくれました。","example_meaning":"Đàn anh đã dẫn tôi đến một nhà hàng mới.","level":"n4"},
{"word":"案内する","reading":"あんないする","meaning":"hướng dẫn, dẫn đường","hanviet":"án nội","note":"TRỢ TỪ: AがBをCに案内する ▸ を = người được dẫn ▸ に = nơi. Ghép: 案内してあげる／くれる／もらう. Khiêm nhường: ご案内する; nhờ người trên: ご案内いただく.","example":"京都に来た友達を、市内の名所に案内してあげました。","example_reading":"きょうとにきたともだちを、しないのめいしょにあんないしてあげました。","example_meaning":"Tôi đã dẫn người bạn đến Kyoto đi thăm các danh lam trong thành phố.","level":"n4"},
{"word":"差し上げる","reading":"さしあげる","meaning":"biếu, dâng (khiêm nhường của あげる)","hanviet":"sai thượng","note":"TRỢ TỪ: 私がお客様／先生にCをさしあげる ▸ に = người nhận (là bề trên) ▸ を = vật biếu. Chỉ dùng cho hành động của MÌNH/phía mình, không dùng tôn kính cho người khác.","antonym":"いただく: nhận (khiêm nhường) / 頂戴する（ちょうだいする）: nhận (rất khiêm nhường)","antonym_hanviet":" / đính đới","example":"お客様に新商品のサンプルを差し上げました。","example_reading":"おきゃくさまにしんしょうひんのさんぷるをさしあげました。","example_meaning":"Tôi đã biếu khách hàng mẫu thử sản phẩm mới.","level":"n3"},
{"word":"贈る","reading":"おくる","meaning":"tặng, gửi tặng","hanviet":"tặng","note":"TRỢ TỪ: AがBにCを贈る ▸ に = người nhận ▸ を = quà (trang trọng/chính thức, trao lời chúc, huân chương, tặng thưởng). Dùng cả cho nhóm: ～に感謝の言葉を贈る.","antonym":"受け取る（うけとる）: nhận","antonym_hanviet":"thụ thủ","example":"卒業する生徒に記念品を贈りました。","example_reading":"そつぎょうするせいとにきねんひんをおくりました。","example_meaning":"Chúng tôi đã tặng học sinh sắp tốt nghiệp món quà kỷ niệm.","level":"n3"},
{"word":"受け取る","reading":"うけとる","meaning":"nhận lấy (một cách chủ động)","hanviet":"thụ thủ","note":"TRỢ TỪ: AがBからCを受け取る ▸ から = nguồn gửi (dùng から, ít dùng に) ▸ を = vật. Nhấn mạnh hành vi nhận (thư từ, tiền, bưu kiện), khác もらう (nhận như món quà).","antonym":"払う（はらう）: trả tiền / 支払う（しはらう）: thanh toán / 送る（おくる）: gửi","antonym_hanviet":"phất / chi phất / tống","example":"宅配便を受け取るために家にいます。","example_reading":"たくはいびんをうけとるためにいえにいます。","example_meaning":"Tôi ở nhà để nhận bưu kiện.","level":"n3"},
{"word":"譲る","reading":"ゆずる","meaning":"nhường, chuyển nhượng","hanviet":"nhượng","note":"TRỢ TỪ: AがBにCを譲る ▸ に = người được nhường ▸ を = vật/chỗ ngồi/quyền. Vừa nghĩa 'nhường' vừa 'bán lại giá rẻ'. Dạng bị động nhận: 譲ってもらう.","example":"電車でお年寄りに席を譲りました。","example_reading":"でんしゃでおとしよりにせきをゆずりました。","example_meaning":"Trên tàu tôi đã nhường chỗ cho người già.","level":"n3"},
{"word":"おごる","reading":"おごる","meaning":"khao, mời (trả tiền hộ)","antonym":"割り勘（わりかん）: chia tiền đều","antonym_hanviet":"cát khám","note":"TRỢ TỪ: AがBにCをおごる ▸ に = người được khao ▸ を = bữa ăn/đồ uống. Đồng nghĩa: ごちそうする. Người được khao: ごちそうになる／おごってもらう.","example":"今日は私が後輩にランチをおごります。","example_reading":"きょうはわたしがこうはいにらんちをおごります。","example_meaning":"Hôm nay tôi khao đàn em bữa trưa.","level":"n3"},
{"word":"教わる","reading":"おそわる","meaning":"được dạy, học (từ ai đó chỉ cho)","hanviet":"giáo","note":"TRỢ TỪ: AがBにCを教わる ▸ に／から = người dạy ▸ を = nội dung. Là dạng 'nhận' của 教える (≈ 教えてもらう). Khác 習う: 教わる nhấn việc được ai chỉ cho một việc cụ thể (đường đi, cách làm); 習う thiên về học đều đặn (khóa học, môn học).","antonym":"教える（おしえる）: dạy","antonym_hanviet":"giáo","example":"道に迷ったので、通りがかりの人に駅への行き方を教わりました。","example_reading":"みちにまよったので、とおりがかりのひとにえきへのいきかたをおそわりました。","example_meaning":"Vì bị lạc đường nên tôi được một người đi ngang chỉ cho cách đến ga.","level":"n3"},
{"word":"預ける","reading":"あずける","meaning":"gửi (giữ hộ), giao cho giữ","hanviet":"dự","note":"TRỢ TỪ: AがBにCを預ける ▸ に = người/nơi nhận giữ ▸ を = vật/tiền/con cái. Đối lập: 預かる (phía nhận giữ). Hay gặp: 荷物を預ける、お金を銀行に預ける、子どもを保育園に預ける.","antonym":"引き取る（ひきとる）: nhận lại / 預かる（あずかる）: nhận giữ / 下ろす（おろす）: rút (tiền)","antonym_hanviet":"dẫn thủ / dự / hạ","example":"チェックインの前に、荷物をフロントに預けました。","example_reading":"ちぇっくいんのまえに、にもつをふろんとにあずけました。","example_meaning":"Trước khi nhận phòng, tôi đã gửi hành lý ở quầy lễ tân.","level":"n3"},
{"word":"預かる","reading":"あずかる","meaning":"nhận giữ hộ, trông giữ","hanviet":"dự","note":"TRỢ TỪ: AがBからCを預かる ▸ から = người gửi (に cũng gặp nhưng から rõ nghĩa hơn) ▸ を = vật/trẻ nhỏ/thú cưng. Đối lập: 預ける. Chú ý: 預かる = tôi là người GIỮ, không phải người gửi. Lịch sự: お預かりします.","antonym":"預ける（あずける）: gửi","antonym_hanviet":"dự","example":"友達が旅行している間、犬を預かることになりました。","example_reading":"ともだちがりょこうしているあいだ、いぬをあずかることになりました。","example_meaning":"Trong lúc bạn đi du lịch, tôi nhận trông giúp con chó.","level":"n3"},
{"word":"配る","reading":"くばる","meaning":"phát, chia phát (cho nhiều người)","hanviet":"phối","antonym":"集める（あつめる）: thu gom","antonym_hanviet":"tập","note":"TRỢ TỪ: AがBにCを配る ▸ に = những người nhận (thường nhiều người, có thể lược) ▸ を = vật. Khác 渡す (đưa cho một đối tượng): 配る = phát lần lượt cho từng người. Cụm khác: ビラを配る、気を配る (để ý chu đáo).","example":"会議の前に、全員に資料を配ってください。","example_reading":"かいぎのまえに、ぜんいんにしりょうをくばってください。","example_meaning":"Trước cuộc họp, hãy phát tài liệu cho mọi người.","level":"n3"},
{"word":"ごちそうする／ごちそうになる","reading":"ごちそうする／ごちそうになる","meaning":"mời ăn, khao ／ được mời ăn, được khao","note":"TRỢ TỪ: AがBにCをごちそうする ▸ に = người được mời ▸ を = bữa ăn. Phía nhận: BがAにごちそうになる ▸ に = người mời. Lịch sự hơn おごる, dùng được với người trên. Khi được mời, cách nói tự nhiên nhất là ごちそうになりました (hoặc ごちそうしてもらう／いただく).","example":"昨日は部長にお昼をごちそうになりました。","example_reading":"きのうはぶちょうにおひるをごちそうになりました。","example_meaning":"Hôm qua tôi được trưởng phòng mời bữa trưa.","level":"n3"},
{"word":"贈り物","reading":"おくりもの","meaning":"quà tặng, vật tặng","hanviet":"tặng vật","note":"Danh từ của 贈る, trang trọng hơn プレゼント. Mẫu: Nへの贈り物 (quà dành cho N) ▸ 贈り物をする／選ぶ ▸ 友達からの贈り物 (quà từ bạn).","example":"母への贈り物に、スカーフを選びました。","example_reading":"ははへのおくりものに、すかーふをえらびました。","example_meaning":"Tôi đã chọn một chiếc khăn quàng làm quà tặng mẹ.","level":"n3"},
{"word":"お祝い","reading":"おいわい","meaning":"lời chúc mừng, quà mừng, tiệc mừng","hanviet":"chúc","antonym":"お悔やみ（おくやみ）: lời chia buồn","antonym_hanviet":"hối","note":"Hay gặp: お祝いをあげる／もらう／くれる (quà mừng) ▸ お祝いを言う (nói lời chúc mừng) ▸ お祝いをする (tổ chức ăn mừng). Gắn với dịp: 結婚祝い、出産祝い、入学祝い、合格祝い. Quà đáp lại: お返し／内祝い.","example":"友達の結婚のお祝いに、ペアのグラスを贈りました。","example_reading":"ともだちのけっこんのおいわいに、ぺあのぐらすをおくりました。","example_meaning":"Tôi đã tặng một cặp ly để mừng đám cưới của bạn.","level":"n3"},
{"word":"お礼","reading":"おれい","meaning":"lời cảm ơn, quà cảm ơn","hanviet":"lễ","note":"Hay gặp: お礼を言う (nói lời cảm ơn) ▸ お礼をする (đáp lễ bằng quà/hành động) ▸ お礼状 (thư cảm ơn). Mẫu: ～のお礼に＋hành động (để đáp lại ...). Người được cảm ơn đi với に: 先生にお礼を言う.","example":"手伝ってもらったお礼に、昼ご飯をおごりました。","example_reading":"てつだってもらったおれいに、ひるごはんをおごりました。","example_meaning":"Để cảm ơn vì đã được giúp, tôi đã khao bữa trưa.","level":"n3"},
{"word":"お返し","reading":"おかえし","meaning":"quà đáp lễ, sự đáp lại","hanviet":"phản","note":"Danh từ của 返す: quà/hành động đáp lại khi đã nhận gì đó. Mẫu: Nにお返しをする／～のお返しに～. Văn hóa: 3/14 ホワイトデー là ngày đáp lễ quà Valentine; ở một số dịp (mừng cưới, thăm bệnh) có quy ước 半返し (đáp lại khoảng một nửa giá trị).","example":"バレンタインのお返しに、手作りのクッキーを渡しました。","example_reading":"ばれんたいんのおかえしに、てづくりのくっきーをわたしました。","example_meaning":"Để đáp lại quà Valentine, tôi đã đưa bánh quy tự làm.","level":"n3"},
{"word":"お年玉","reading":"おとしだま","meaning":"tiền mừng tuổi (dịp Tết dương lịch)","hanviet":"niên ngọc","note":"Văn hóa: người lớn cho trẻ nhỏ tiền đựng trong phong bì nhỏ dịp Tết. Mẫu: 子どもにお年玉をあげる ▸ 祖父母からお年玉をもらう. Người cho là người lớn, người nhận là trẻ em.","example":"祖父母からお年玉をもらって、うれしかったです。","example_reading":"そふぼからおとしだまをもらって、うれしかったです。","example_meaning":"Được ông bà mừng tuổi, tôi rất vui.","level":"n3"},
{"word":"届く","reading":"とどく","meaning":"đến nơi, được gửi tới (tự động từ)","hanviet":"giới","note":"TRỢ TỪ: CがBに届く ▸ が = vật/tin được gửi ▸ に = người/nơi nhận ▸ から = người gửi. Cặp với 届ける (tha động từ: AがBにCを届ける). Hay gặp: 荷物が届く、メールが届く、思いが届く.","example":"母から小包が届きました。","example_reading":"ははからこづつみがとどきました。","example_meaning":"Bưu kiện từ mẹ đã tới.","level":"n3"},
{"word":"お見舞い","reading":"おみまい","meaning":"thăm bệnh; quà thăm bệnh","hanviet":"kiến vũ","note":"Hay gặp: お見舞いに行く／お見舞いを持っていく／お見舞いをもらう. Văn hóa: tránh tặng chậu cây (鉢植え – ngụ ý 'bệnh bám rễ'); nên tặng đồ ăn nhẹ, tạp chí, hoa cắm sẵn (nếu bệnh viện cho phép). Đáp lại: お見舞い返し／快気祝い.","example":"入院した友達に、お見舞いの花を贈りました。","example_reading":"にゅういんしたともだちに、おみまいのはなをおくりました。","example_meaning":"Tôi đã gửi hoa thăm bệnh cho người bạn nhập viện.","level":"n3"},
{"word":"お小遣い","reading":"おこづかい","meaning":"tiền tiêu vặt","hanviet":"tiểu khiển","note":"Danh từ: 親にお小遣いをもらう／祖母がお小遣いをくれる／弟にお小遣いをあげる. Người cho thường là người lớn trong nhà, người nhận là trẻ em hoặc người trẻ.","example":"祖母が毎月お小遣いをくれます。","example_reading":"そぼがまいつきおこづかいをくれます。","example_meaning":"Bà cho tôi tiền tiêu vặt mỗi tháng.","level":"n3"},
{"word":"世話","reading":"せわ","meaning":"sự chăm sóc, giúp đỡ","hanviet":"thế thoại","note":"TRỢ TỪ: AがBの世話をする (cho: chăm sóc B) ↔ BがAにお世話になる (nhận: được A giúp đỡ). Nền tảng của lời chào công việc: いつもお世話になっております. 世話になる = mang ơn; 世話を焼く = lo hộ.","example":"入院中は、友達に何かと世話になりました。","example_reading":"にゅういんちゅうは、ともだちになにかとせわになりました。","example_meaning":"Trong lúc nằm viện, tôi đã được bạn bè giúp đỡ đủ điều.","level":"n3"},
{"word":"感謝する","reading":"かんしゃする","meaning":"biết ơn, cảm ơn","hanviet":"cảm tạ","antonym":"恨む（うらむ）: oán hận","antonym_hanviet":"hận","note":"TRỢ TỪ: AがBに感謝する ▸ に = người được cảm ơn. Có thể thêm lý do: ～てくれたことに感謝する. Cụm hay gặp: 感謝の気持ち／感謝の言葉を贈る／心から感謝申し上げます (trang trọng).","example":"支えてくれた家族に心から感謝しています。","example_reading":"ささえてくれたかぞくにこころからかんしゃしています。","example_meaning":"Tôi thật lòng biết ơn gia đình đã luôn ủng hộ tôi.","level":"n3"},
{"word":"提供する","reading":"ていきょうする","meaning":"cung cấp","hanviet":"đề cung","antonym":"利用する（りようする）: sử dụng","antonym_hanviet":"lợi dụng","note":"TRỢ TỪ: AがBにCを提供する ▸ に = người nhận ▸ を = dịch vụ/thông tin/chỗ ở/cơ hội. Văn phong dịch vụ, doanh nghiệp; không dùng cho quà thông thường.","example":"会社は社員に無料でランチを提供しています。","example_reading":"かいしゃはしゃいんにむりょうでらんちをていきょうしています。","example_meaning":"Công ty cung cấp bữa trưa miễn phí cho nhân viên.","level":"n3"},
{"word":"断る","reading":"ことわる","meaning":"từ chối, khước từ","hanviet":"đoạn","antonym":"引き受ける（ひきうける）: nhận lời / 誘う（さそう）: rủ / 頼む（たのむ）: nhờ","antonym_hanviet":"dẫn thụ / dụ / lại","note":"TRỢ TỪ: AがBのCを断る ▸ を = lời mời/đề nghị/quà ▸ người bị từ chối thường lược hoặc dùng に. Là mặt đối lập của もらう／引き受ける: 贈り物を断る、誘いを断る. Nhẹ hơn: 遠慮する; trang trọng hơn: 辞退する.","example":"せっかくの申し出でしたが、丁寧にお断りしました。","example_reading":"せっかくのもうしでしたが、ていねいにおことわりしました。","example_meaning":"Tuy là lời đề nghị tốt nhưng tôi đã từ chối lịch sự.","level":"n3"},
{"word":"祝う","reading":"いわう","meaning":"chúc mừng, ăn mừng","hanviet":"chúc","note":"TRỢ TỪ: AがBを祝う ▸ を = người/sự kiện được chúc mừng; KHÔNG dùng に cho người. Cụm: 誕生日を祝う、結婚を祝う. Ghép: 祝ってあげる／祝ってくれる／祝ってもらう. Danh từ liên quan: お祝い.","antonym":"悼む（いたむ）: thương tiếc","antonym_hanviet":"điệu","example":"友達に誕生日を祝ってもらいました。","example_reading":"ともだちにたんじょうびをいわってもらいました。","example_meaning":"Tôi được bạn chúc mừng sinh nhật.","level":"n3"},
{"word":"任せる","reading":"まかせる","meaning":"giao phó, phó mặc","hanviet":"nhiệm","note":"TRỢ TỪ: AがBにCを任せる ▸ に = người được giao ▸ を = việc/quyền. Phía nhận: 任される. Lịch sự: お任せください (xin cứ để tôi lo), 任せてもらう (được giao).","example":"この仕事は新人に任せてみようと思います。","example_reading":"このしごとはしんじんにまかせてみようとおもいます。","example_meaning":"Tôi định thử giao việc này cho người mới.","level":"n3"},
{"word":"支払う","reading":"しはらう","meaning":"chi trả, thanh toán","hanviet":"chi phất","note":"TRỢ TỪ: AがBにCを支払う ▸ に = người nhận tiền ▸ を = tiền/chi phí. Trang trọng hơn 払う; hay gặp trong hóa đơn, hợp đồng: 料金を支払う、支払い方法.","antonym":"受け取る（うけとる）: nhận","antonym_hanviet":"thụ thủ","example":"代金は銀行振り込みで支払ってください。","example_reading":"だいきんはぎんこうふりこみでしはらってください。","example_meaning":"Xin hãy thanh toán tiền hàng bằng chuyển khoản ngân hàng.","level":"n3"},
{"word":"勧める","reading":"すすめる","meaning":"khuyên, gợi ý, mời dùng","hanviet":"khuyến","note":"TRỢ TỪ: AがBにCを勧める ▸ に = người được khuyên ▸ を = món/việc. Cũng dùng khi mời đồ ăn thức uống: お茶を勧める. Danh từ: お勧め (món/việc gợi ý). Ghép: 勧めてくれる／勧めてもらう. Lưu ý: 薦める (tiến cử người/vật) viết chữ khác.","antonym":"断る（ことわる）: từ chối","antonym_hanviet":"đoạn","example":"先生が私に留学を勧めてくれました。","example_reading":"せんせいがわたしにりゅうがくをすすめてくれました。","example_meaning":"Thầy đã khuyên tôi đi du học.","level":"n3"},
{"word":"励ます","reading":"はげます","meaning":"động viên, khích lệ","hanviet":"lệ","antonym":"けなす: chê bai","note":"TRỢ TỪ: AがBを励ます ▸ người được động viên đi với を, KHÔNG dùng に. Ghép: 励ましてくれる／励ましてもらう. Danh từ: 励まし (lời động viên) → 励ましの言葉をくれる／いただく.","example":"落ち込んでいた私を、友達が励ましてくれました。","example_reading":"おちこんでいたわたしを、ともだちがはげましてくれました。","example_meaning":"Khi tôi chán nản, bạn đã động viên tôi.","level":"n3"},
{"word":"頂戴する","reading":"ちょうだいする","meaning":"nhận (rất khiêm nhường); (thân mật) xin cho tôi","hanviet":"đính đới","note":"TRỢ TỪ: Aから／にCを頂戴する ▸ dùng trong văn trang trọng: ご連絡を頂戴する、お電話を頂戴する. Dạng ちょうだい (không có する) là cách xin thân mật: ちょうだい = cho tôi với.","antonym":"差し上げる（さしあげる）: biếu","antonym_hanviet":"sai thượng","example":"先日はお心遣いを頂戴し、ありがとうございました。","example_reading":"せんじつはおこころづかいをちょうだいし、ありがとうございました。","example_meaning":"Hôm trước cảm ơn anh đã quan tâm chu đáo.","level":"n2"},
{"word":"与える","reading":"あたえる","meaning":"ban cho, đem lại, gây ra","hanviet":"dữ","note":"TRỢ TỪ: AがBにCを与える ▸ に = đối tượng nhận ▸ を = thứ ban cho (cơ hội, ảnh hưởng, giải thưởng, ấn tượng). Văn viết, trừu tượng. Không dùng cho tặng quà thông thường.","antonym":"奪う（うばう）: cướp","antonym_hanviet":"đoạt","example":"この経験は私に大きな自信を与えてくれました。","example_reading":"このけいけんはわたしにおおきなじしんをあたえてくれました。","example_meaning":"Trải nghiệm này đã mang lại cho tôi sự tự tin lớn.","level":"n2"},
{"word":"寄付する","reading":"きふする","meaning":"quyên góp, ủng hộ","hanviet":"ký phó","note":"TRỢ TỪ: AがBにCを寄付する ▸ に = tổ chức/người nhận ▸ を = tiền/vật phẩm. Với quỹ/tổ chức chỉ dùng に; mục đích dùng のために.","example":"被災地に毎月少しずつ寄付しています。","example_reading":"ひさいちにまいつきすこしずつきふしています。","example_meaning":"Mỗi tháng tôi quyên góp một chút cho vùng thiên tai.","level":"n2"},
{"word":"手渡す","reading":"てわたす","meaning":"trao tận tay","hanviet":"thủ độ","note":"TRỢ TỪ: AがBにCを手渡す ▸ に = người nhận ▸ を = vật. Nhấn việc đưa trực tiếp bằng tay, không qua trung gian (≠ 郵送する、置いておく). Danh từ: 手渡し (手渡しで渡す).","example":"この手紙は本人に直接手渡してください。","example_reading":"このてがみはほんにんにちょくせつてわたしてください。","example_meaning":"Xin hãy trao thư này tận tay cho đương sự.","level":"n2"},
{"word":"拝借する","reading":"はいしゃくする","meaning":"mượn (khiêm nhường của 借りる)","hanviet":"bái tá","antonym":"返却する（へんきゃくする）: trả lại","antonym_hanviet":"phản khước","note":"TRỢ TỪ: Aから／にCを拝借する. Khiêm nhường của 借りる: お借りする (lịch sự thông thường) ▸ 拝借する (trang trọng hơn). Người cho mượn là người trên/khách. Cho mượn: お貸しする (khiêm nhường) ▸ お貸しくださる (tôn kính).","example":"ちょっとペンを拝借してもよろしいでしょうか。","example_reading":"ちょっとぺんをはいしゃくしてもよろしいでしょうか。","example_meaning":"Cho phép tôi mượn tạm cây bút một chút được không ạ?","level":"n2"},
{"word":"拝受する","reading":"はいじゅする","meaning":"nhận (cực kỳ khiêm nhường, dùng trong văn thư)","hanviet":"bái thụ","antonym":"進呈する（しんていする）: xin biếu, tặng","antonym_hanviet":"tiến trình","note":"TRỢ TỪ: Aから／にCを拝受する. Khiêm nhường rất trang trọng, chỉ gặp trong thư từ/văn bản công việc: ～を拝受いたしました (đã nhận được ...). Hội thoại thường dùng いただく／頂戴する.","example":"ご丁寧なお手紙を拝受いたしました。","example_reading":"ごていねいなおてがみをはいじゅいたしました。","example_meaning":"Tôi đã nhận được bức thư chu đáo của quý vị.","level":"n2"},
{"word":"進呈する","reading":"しんていする","meaning":"tặng, xin biếu (trang trọng, hay dùng khi khuyến mãi)","hanviet":"tiến trình","antonym":"拝受する（はいじゅする）: (cực khiêm nhường) nhận","antonym_hanviet":"bái thụ","note":"TRỢ TỪ: AがBにCを進呈する ▸ に = người nhận ▸ を = quà. Trang trọng hơn プレゼントする, thường thấy trong quảng cáo, khuyến mãi: 粗品を進呈いたします. Dùng cho hành động của phía mình.","example":"ご来店の先着百名様に、記念品を進呈いたします。","example_reading":"ごらいてんのせんちゃくひゃくめいさまに、きねんひんをしんていいたします。","example_meaning":"Chúng tôi xin tặng quà kỷ niệm cho 100 quý khách đến cửa hàng đầu tiên.","level":"n2"},
{"word":"差し入れ","reading":"さしいれ","meaning":"đồ tiếp tế, quà động viên (đồ ăn/thức uống mang cho người đang làm việc)","hanviet":"sai nhập","note":"Danh từ (động từ: 差し入れる). Mẫu: Bに差し入れをする／差し入れを持っていく／差し入れをもらう. Mang đến cho người đang bận (ôn thi, tăng ca, luyện tập) để động viên, thường không cần đáp lễ.","example":"残業している同僚に、差し入れのコーヒーを持っていきました。","example_reading":"ざんぎょうしているどうりょうに、さしいれのこーひーをもっていきました。","example_meaning":"Tôi mang cà phê tiếp tế cho đồng nghiệp đang tăng ca.","level":"n2"},
{"word":"手土産","reading":"てみやげ","meaning":"quà mang theo khi đến thăm","hanviet":"thủ thổ sản","note":"Quà mang khi đến nhà hoặc công ty người khác (khác お土産: quà mua khi đi xa về). Mẫu: 手土産を持っていく／渡す. Nên chọn món vừa phải, dễ chia; câu nói kèm: つまらないものですが….","example":"取引先を訪ねる時は、手土産を持っていきます。","example_reading":"とりひきさきをたずねるときは、てみやげをもっていきます。","example_meaning":"Khi đến thăm đối tác, tôi mang theo quà biếu.","level":"n2"},
{"word":"お中元／お歳暮","reading":"おちゅうげん／おせいぼ","meaning":"quà biếu giữa năm／quà biếu cuối năm","hanviet":"trung nguyên tuế mộ","note":"Quà biếu theo mùa gửi cho người đã giúp đỡ mình trong năm (お中元: tháng 7–8, お歳暮: tháng 12). Mẫu: お歳暮を贈る／お歳暮をいただく／お中元のお礼. Nhận được nên gửi thư/điện thoại cảm ơn.","example":"毎年、お世話になった方にお歳暮を贈っています。","example_reading":"まいとし、おせわになったかたにおせいぼをおくっています。","example_meaning":"Hằng năm tôi gửi quà biếu cuối năm cho những người đã giúp đỡ mình.","level":"n2"},
{"word":"恩返し","reading":"おんがえし","meaning":"đền ơn, báo đáp","hanviet":"ân phản","antonym":"恩知らず（おんしらず）: kẻ vô ơn","antonym_hanviet":"ân tri","note":"Mẫu: AにB恩返しをする ▸ 恩 = ơn. Cụm gốc: 恩を受ける／恩に着る (mang ơn) → 恩返しをする (đền ơn). Cũng dùng trong truyện dân gian (鶴の恩返し).","example":"育ててくれた両親に恩返しがしたいです。","example_reading":"そだててくれたりょうしんにおんがえしがしたいです。","example_meaning":"Tôi muốn đền ơn cha mẹ đã nuôi nấng mình.","level":"n2"},
{"word":"仕送り","reading":"しおくり","meaning":"gửi tiền/đồ về nuôi gia đình hoặc con","hanviet":"sĩ tống","note":"TRỢ TỪ: AがBにCを仕送りする ▸ に = người nhận (gia đình, con cái) ▸ を = tiền/đồ. Phía nhận: 親から仕送りをもらう／受ける. Gắn với du học sinh, người đi làm xa.","example":"毎月、田舎の両親に仕送りをしています。","example_reading":"まいつき、いなかのりょうしんにしおくりをしています。","example_meaning":"Mỗi tháng tôi gửi tiền về cho bố mẹ ở quê.","level":"n2"},
{"word":"援助する","reading":"えんじょする","meaning":"viện trợ, hỗ trợ","hanviet":"viện trợ","note":"TRỢ TỪ: AがBにCを援助する ▸ に = người/quốc gia nhận ▸ を = tiền/vật chất. Phía nhận: 援助を受ける. Cụm: 経済援助、資金援助、緊急援助.","example":"親が学費を援助してくれました。","example_reading":"おやががくひをえんじょしてくれました。","example_meaning":"Bố mẹ đã hỗ trợ tôi học phí.","level":"n2"},
{"word":"振る舞う","reading":"ふるまう","meaning":"đãi, khoản đãi (món ăn, đồ uống)","hanviet":"chấn vũ","note":"TRỢ TỪ: AがBにCを振る舞う ▸ に = khách ▸ を = món ăn/rượu. Mang sắc thái chủ nhà mời rộng rãi. Còn nghĩa khác: 'cư xử' (明るく振る舞う) — phân biệt theo trợ từ và ngữ cảnh.","example":"新年会では、店主が客に酒を振る舞ってくれました。","example_reading":"しんねんかいでは、てんしゅがきゃくにさけをふるまってくれました。","example_meaning":"Trong tiệc tân niên, chủ quán đã đãi khách rượu.","level":"n2"},
{"word":"引き渡す","reading":"ひきわたす","meaning":"bàn giao, giao lại","hanviet":"dẫn độ","note":"TRỢ TỪ: AがBにCを引き渡す ▸ に = người nhận ▸ を = chìa khóa/tài sản/nghi phạm. Nhấn việc chuyển giao chính thức, có thủ tục (khác 渡す đưa thông thường). Danh từ: 引き渡し.","antonym":"引き取る（ひきとる）: nhận về","antonym_hanviet":"dẫn thủ","example":"工事が終わったので、鍵を所有者に引き渡しました。","example_reading":"こうじがおわったので、かぎをしょゆうしゃにひきわたしました。","example_meaning":"Vì công trình đã xong nên chìa khóa đã được bàn giao cho chủ sở hữu.","level":"n2"},
{"word":"貸し出す","reading":"かしだす","meaning":"cho mượn (dịch vụ, thư viện)","hanviet":"thải xuất","note":"TRỢ TỪ: AがBにCを貸し出す ▸ に = người mượn ▸ を = sách/đồ. Tổ chức cho người dùng mượn theo quy định. Danh từ: 貸し出し.","antonym":"返却する（へんきゃくする）: hoàn trả","antonym_hanviet":"phản khước","example":"図書館では、一人五冊まで本を貸し出しています。","example_reading":"としょかんでは、ひとりごさつまでほんをかしだしています。","example_meaning":"Thư viện cho mượn tối đa năm cuốn sách mỗi người.","level":"n2"},
{"word":"受け継ぐ／引き継ぐ","reading":"うけつぐ／ひきつぐ","meaning":"kế thừa／tiếp quản, bàn giao lại","hanviet":"thụ kế dẫn","note":"TRỢ TỪ: AがBからCを受け継ぐ ▸ から = người/thế hệ trao lại ▸ を = nghề/truyền thống/tài sản (nhấn 'nhận lại từ thế hệ trước'). 引き継ぐ: tiếp quản công việc/trách nhiệm, vừa là 'nhận' (前任者から引き継ぐ) vừa là 'giao lại' (後任者に引き継ぐ).","example":"私は父からこの店を受け継ぎました。","example_reading":"わたしはちちからこのみせをうけつぎました。","example_meaning":"Tôi đã kế thừa cửa hàng này từ bố.","level":"n2"},
{"word":"振り込む","reading":"ふりこむ","meaning":"chuyển khoản","hanviet":"chấn","antonym":"引き出す（ひきだす）: rút tiền","antonym_hanviet":"dẫn xuất","note":"TRỢ TỪ: AがBにCを振り込む ▸ に = tài khoản/người nhận ▸ を = tiền. Danh từ: 振り込み. Phía nhận: 振り込まれる (tiền được chuyển vào).","example":"代金は明日までに指定の口座に振り込んでください。","example_reading":"だいきんはあすまでにしていのこうざにふりこんでください。","example_meaning":"Hãy chuyển khoản tiền hàng vào tài khoản chỉ định trước ngày mai.","level":"n2"},
{"word":"差し出す","reading":"さしだす","meaning":"chìa ra, đưa ra","hanviet":"sai xuất","note":"TRỢ TỪ: AがBにCを差し出す ▸ に = người nhận ▸ を = tay/vật/tờ giấy. Nhấn hành động chìa ra trước mặt (名刺を差し出す), khác 渡す (đưa chung chung). Từ liên quan: 差出人 (người gửi).","antonym":"受け取る（うけとる）: nhận","antonym_hanviet":"thụ thủ","example":"取引先に名刺を差し出しました。","example_reading":"とりひきさきにめいしをさしだしました。","example_meaning":"Tôi đã chìa danh thiếp cho đối tác.","level":"n2"},
{"word":"返却する","reading":"へんきゃくする","meaning":"hoàn trả (văn phong dịch vụ)","hanviet":"phản khước","antonym":"貸し出す（かしだす）: cho mượn / 拝借する（はいしゃくする）: mượn","antonym_hanviet":"thải xuất / bái tá","note":"TRỢ TỪ: AがBにCを返却する ▸ に = nơi/người nhận lại ▸ を = vật mượn. Trang trọng hơn 返す, hay gặp ở thư viện, cho thuê: 返却期限、返却口.","example":"借りた本は、期限までに図書館に返却してください。","example_reading":"かりたほんは、きげんまでにとしょかんにへんきゃくしてください。","example_meaning":"Sách đã mượn xin hãy trả cho thư viện trước hạn.","level":"n2"},
{"word":"謝礼","reading":"しゃれい","meaning":"tiền/quà cảm tạ","hanviet":"tạ lễ","note":"Danh từ: Bに謝礼を渡す／払う ▸ 謝礼をもらう／いただく. Khác お礼 (lời/quà cảm ơn chung): 謝礼 là khoản thù lao tượng trưng trả cho người đã giúp (diễn giả, người cung cấp thông tin, người làm thử).","example":"講演をしてくれた先生に、謝礼をお渡ししました。","example_reading":"こうえんをしてくれたせんせいに、しゃれいをおわたししました。","example_meaning":"Chúng tôi đã đưa tiền cảm tạ cho thầy đã đến diễn thuyết.","level":"n2"},
{"word":"引き受ける","reading":"ひきうける","meaning":"nhận lời, đảm nhận","hanviet":"dẫn thụ","antonym":"断る（ことわる）: từ chối / 頼む（たのむ）: nhờ","antonym_hanviet":"đoạn / lại","note":"TRỢ TỪ: AがCを引き受ける ▸ を = việc/trách nhiệm ▸ người nhờ: Bに頼まれて／Bから頼まれて. Chuỗi: 頼む → 引き受ける／断る. Danh từ gần nghĩa: 引き受け. Lịch sự: お引き受けします.","example":"友達に頼まれて、司会を引き受けました。","example_reading":"ともだちにたのまれて、しかいをひきうけました。","example_meaning":"Được bạn nhờ nên tôi đã nhận làm người dẫn chương trình.","level":"n2"},
{"word":"見送る","reading":"みおくる","meaning":"tiễn (ra ga, sân bay); bỏ qua, hoãn","hanviet":"kiến tống","note":"TRỢ TỪ: AがBを見送る ▸ người được tiễn đi với を. Ghép: 見送ってくれる／見送ってもらう. Cặp đối: 出迎える (đón). Nghĩa khác: bỏ qua/hoãn (計画を見送る).","antonym":"迎える（むかえる）: đón / 出迎える（でむかえる）: ra đón","antonym_hanviet":"nghênh / xuất nghênh","example":"空港まで友達が見送りに来てくれました。","example_reading":"くうこうまでともだちがみおくりにきてくれました。","example_meaning":"Bạn đã ra tận sân bay tiễn tôi.","level":"n2"},
{"word":"立て替える","reading":"たてかえる","meaning":"ứng trước tiền hộ","hanviet":"lập thế","note":"TRỢ TỪ: AがBにCを立て替える ▸ に = người được ứng hộ ▸ を = khoản tiền. Ghép: 立て替えてあげる／くれる／もらう. Sau đó phải hoàn lại: 立て替えた分を返す. Danh từ: 立て替え.","example":"財布を忘れたので、先輩に代金を立て替えてもらいました。","example_reading":"さいふをわすれたので、せんぱいにだいきんをたてかえてもらいました。","example_meaning":"Vì quên ví nên tôi nhờ anh khóa trên ứng trước tiền hộ.","level":"n2"},
{"word":"賜る","reading":"たまわる","meaning":"(khiêm nhường) nhận từ bề trên; (trang trọng) ban cho","hanviet":"tứ","note":"TRỢ TỪ: Aから／よりCを賜る ▸ を = ân huệ/sự ưu ái. Cực kỳ trang trọng, gần như chỉ gặp ở cụm cố định trong văn thư, diễn văn: ご愛顧を賜る、ご指導を賜る、ご教示賜りたく. Tầng cao hơn 頂戴する.","example":"平素は格別のご愛顧を賜り、厚く御礼申し上げます。","example_reading":"へいそはかくべつのごあいこをたまわり、あつくおれいもうしあげます。","example_meaning":"Xin chân thành cảm ơn quý khách đã luôn ưu ái chiếu cố.","level":"n1"},
{"word":"授ける","reading":"さずける","meaning":"ban, truyền cho (tri thức, bí quyết, danh hiệu)","hanviet":"thụ","note":"TRỢ TỪ: AがBにCを授ける ▸ に = người nhận ▸ を = tri thức/danh hiệu/quyền. Phía nhận: 授かる (子どもを授かる = được trời ban con). Văn viết, người cho ở vị thế trên.","antonym":"授かる（さずかる）: được ban cho","antonym_hanviet":"thụ","example":"師は弟子に奥義を授けた。","example_reading":"しはでしにおうぎをさずけた。","example_meaning":"Thầy đã truyền bí quyết cho đệ tử.","level":"n1"},
{"word":"授与する","reading":"じゅよする","meaning":"trao tặng chính thức (bằng cấp, huân chương)","hanviet":"thụ dữ","note":"TRỢ TỪ: AがBにCを授与する ▸ に = người nhận ▸ を = học vị/bằng khen/huy chương. Bị động: 授与される. Văn phong nghi lễ, hành chính.","example":"学長は卒業生に学位を授与した。","example_reading":"がくちょうはそつぎょうせいにがくいをじゅよした。","example_meaning":"Hiệu trưởng đã trao học vị cho các sinh viên tốt nghiệp.","level":"n1"},
{"word":"寄贈する","reading":"きぞうする","meaning":"hiến tặng (sách, tác phẩm cho tổ chức)","hanviet":"ký tặng","note":"TRỢ TỪ: AがBにCを寄贈する ▸ に = tổ chức (trường, thư viện, bảo tàng) ▸ を = sách/tác phẩm/thiết bị. Khác 寄付する (chủ yếu tiền). Danh từ: 寄贈品／寄贈者.","example":"卒業生が母校の図書館に蔵書を寄贈しました。","example_reading":"そつぎょうせいがぼこうのとしょかんにぞうしょをきぞうしました。","example_meaning":"Cựu sinh viên đã tặng sách quý cho thư viện trường cũ.","level":"n1"},
{"word":"贈与する","reading":"ぞうよする","meaning":"tặng cho (thuật ngữ pháp lý)","hanviet":"tặng dữ","note":"TRỢ TỪ: AがBにCを贈与する ▸ に = người nhận ▸ を = tài sản. Hợp đồng tặng cho không điều kiện; dạng ghép: 生前贈与、贈与税、贈与契約.","antonym":"受贈する（じゅぞうする）: nhận tặng","antonym_hanviet":"thụ tặng","example":"親から子へ財産を贈与する場合は、贈与税がかかります。","example_reading":"おやからこへざいさんをぞうよするばあいは、ぞうよぜいがかかります。","example_meaning":"Khi cha mẹ tặng tài sản cho con thì phát sinh thuế tặng cho.","level":"n1"},
{"word":"譲渡する","reading":"じょうとする","meaning":"chuyển nhượng","hanviet":"nhượng độ","note":"TRỢ TỪ: AがBにCを譲渡する ▸ に = người nhận ▸ を = quyền/cổ phiếu/đất đai. Có thể có giá (有償) hoặc không (無償). Danh từ: 譲渡契約、権利の譲渡.","antonym":"譲り受ける（ゆずりうける）: nhận chuyển nhượng","antonym_hanviet":"nhượng thụ","example":"彼は保有する株式をすべて長男に譲渡しました。","example_reading":"かれはほゆうするかぶしきをすべてちょうなんにじょうとしました。","example_meaning":"Ông ấy đã chuyển nhượng toàn bộ cổ phiếu đang nắm cho con trai cả.","level":"n1"},
{"word":"還元する","reading":"かんげんする","meaning":"hoàn lại, đóng góp lại","hanviet":"hoàn nguyên","note":"TRỢ TỪ: AがBにCを還元する ▸ に = khách hàng/xã hội/cổ đông ▸ を = lợi nhuận/thành quả. Mẫu quen thuộc: 利益を顧客に還元する、地域に還元する.","example":"売り上げの一部を地域社会に還元したいと考えています。","example_reading":"うりあげのいちぶをちいきしゃかいにかんげんしたいとかんがえています。","example_meaning":"Chúng tôi muốn đem một phần doanh thu đóng góp lại cho cộng đồng địa phương.","level":"n1"},
{"word":"恵まれる","reading":"めぐまれる","meaning":"may mắn có được, được trời ban","hanviet":"huệ","note":"TRỢ TỪ: AはBに恵まれる ▸ に = thứ được ban (才能・環境・友人・天気). Là thể bị động của 恵む (ban phát, sắc thái bề trên) nhưng người Nhật gần như chỉ dùng dạng 恵まれる.","example":"私は素晴らしい先生と仲間に恵まれました。","example_reading":"わたしはすばらしいせんせいとなかまにめぐまれました。","example_meaning":"Tôi may mắn có được thầy cô và bạn bè tuyệt vời.","level":"n1"},
{"word":"授かる","reading":"さずかる","meaning":"được ban cho (con cái, tài năng, bí quyết)","hanviet":"thụ","note":"TRỢ TỪ: AがBにCを授かる ▸ に／から = người/trời ban ▸ を = thứ được ban. Phía cho: 授ける. Cụm: 子どもを授かる、才能を授かる、教えを授かる.","antonym":"授ける（さずける）: ban cho","antonym_hanviet":"thụ","example":"結婚して三年目に、ようやく子どもを授かりました。","example_reading":"けっこんしてさんねんめに、ようやくこどもをさずかりました。","example_meaning":"Năm thứ ba sau khi cưới, cuối cùng chúng tôi cũng có được một đứa con.","level":"n1"},
{"word":"授受","reading":"じゅじゅ","meaning":"trao và nhận (hai chiều)","hanviet":"thụ thụ","note":"Chính là từ trong 授受表現 (diễn đạt cho–nhận). Danh từ Hán, văn viết/pháp lý: 金銭の授受 (trao nhận tiền), 物品の授受. Mẫu: ～の授受が行われる／授受する.","example":"金銭の授受があったかどうかが捜査の焦点となっている。","example_reading":"きんせんのじゅじゅがあったかどうかがそうさのしょうてんとなっている。","example_meaning":"Việc có xảy ra trao nhận tiền hay không là trọng tâm của cuộc điều tra.","level":"n1"},
{"word":"贈呈する","reading":"ぞうていする","meaning":"trao tặng (nghi lễ, công khai)","hanviet":"tặng trình","antonym":"受領する（じゅりょうする）: tiếp nhận","antonym_hanviet":"thụ lĩnh","note":"TRỢ TỪ: AがBにCを贈呈する ▸ に = người nhận ▸ を = quà/kỷ niệm/hoa. Dùng trong nghi thức trước đông người: 花束を贈呈する、記念品贈呈. Khác 進呈 (hạ mình, khiêm nhường) và 授与 (bằng cấp, huân chương).","example":"式典で、功労者に記念品が贈呈されました。","example_reading":"しきてんで、こうろうしゃにきねんひんがぞうていされました。","example_meaning":"Tại buổi lễ, quà kỷ niệm đã được trao tặng cho những người có công.","level":"n1"},
{"word":"供与する","reading":"きょよする","meaning":"cung cấp, trao cho (viện trợ, tiện lợi)","hanviet":"cung dữ","antonym":"受領する（じゅりょうする）: tiếp nhận","antonym_hanviet":"thụ lĩnh","note":"TRỢ TỪ: AがBにCを供与する ▸ に = quốc gia/tổ chức nhận ▸ を = tiền/thiết bị/lợi ích. Hay gặp trong ngoại giao, kinh tế: 資金供与、便宜供与、技術供与.","example":"政府は被災国に緊急の資金を供与しました。","example_reading":"せいふはひさいこくにきんきゅうのしきんをきょよしました。","example_meaning":"Chính phủ đã cung cấp nguồn vốn khẩn cấp cho quốc gia bị thiên tai.","level":"n1"},
{"word":"貸与する","reading":"たいよする","meaning":"cho mượn/cho vay (chính thức)","hanviet":"thải dữ","note":"TRỢ TỪ: AがBにCを貸与する ▸ に = người mượn ▸ を = vật/tiền. Văn bản chính thức, hợp đồng: 制服を貸与する、貸与型奨学金 (học bổng dạng vay). Đối lập về hướng: 借用する.","antonym":"借用する（しゃくようする）: mượn","antonym_hanviet":"tá dụng","example":"会社は社員にノートパソコンを貸与しています。","example_reading":"かいしゃはしゃいんにのーとぱそこんをたいよしています。","example_meaning":"Công ty cho nhân viên mượn máy tính xách tay.","level":"n1"},
{"word":"施す","reading":"ほどこす","meaning":"ban phát; thi hành, áp dụng","hanviet":"thi","note":"TRỢ TỪ: AがBにCを施す ▸ に = đối tượng ▸ を = ơn huệ/biện pháp/xử lý. Ba nghĩa: ① ban ơn, bố thí (施し = của bố thí) ② thi hành (治療を施す、対策を施す) ③ trang trí (装飾を施す).","example":"医師は患者に適切な治療を施しました。","example_reading":"いしはかんじゃにてきせつなちりょうをほどこしました。","example_meaning":"Bác sĩ đã tiến hành điều trị thích hợp cho bệnh nhân.","level":"n1"},
{"word":"返礼する","reading":"へんれいする","meaning":"đáp lễ (trang trọng)","hanviet":"phản lễ","note":"Mẫu: Bに返礼する／返礼の品／返礼品. Trang trọng hơn お返し. Hay gặp: ふるさと納税の返礼品 (quà tri ân).","example":"寄付をしてくれた方々に、返礼として記念品を送りました。","example_reading":"きふをしてくれたかたがたに、へんれいとしてきねんひんをおくりました。","example_meaning":"Chúng tôi đã gửi quà kỷ niệm đáp lễ cho những người đã quyên góp.","level":"n1"},
{"word":"返還する","reading":"へんかんする","meaning":"hoàn trả, trả lại (chính thức, pháp lý)","hanviet":"phản hoàn","antonym":"借用する（しゃくようする）: mượn dùng","antonym_hanviet":"tá dụng","note":"TRỢ TỪ: AがBにCを返還する ▸ に = bên nhận lại ▸ を = tài sản/lãnh thổ/tiền. Văn bản chính thức: 領土の返還、優勝旗の返還、資金の返還. Khác 返す (thông thường) và 返却する (dịch vụ).","example":"前回の優勝校が、優勝旗を大会本部に返還しました。","example_reading":"ぜんかいのゆうしょうこうが、ゆうしょうきをたいかいほんぶにへんかんしました。","example_meaning":"Trường vô địch kỳ trước đã trả lại cờ vô địch cho ban tổ chức.","level":"n1"},
{"word":"賜物","reading":"たまもの","meaning":"thành quả nhờ ơn, nhờ công sức","hanviet":"tứ vật","note":"Danh từ trang trọng: ～の賜物 = 'nhờ (công sức/ơn huệ của…)'. Mẫu: 努力の賜物、皆様のご支援の賜物. Gốc từ 賜る (nhận ơn).","example":"今回の成功は、皆様のご支援の賜物です。","example_reading":"こんかいのせいこうは、みなさまのごしえんのたまものです。","example_meaning":"Thành công lần này là nhờ sự ủng hộ của quý vị.","level":"n1"},
{"word":"辞退する","reading":"じたいする","meaning":"từ chối (khiêm tốn), xin không nhận","hanviet":"từ thoái","antonym":"受諾する（じゅだくする）: chấp nhận","antonym_hanviet":"thụ nặc","note":"TRỢ TỪ: AがCを辞退する ▸ を = lời mời/giải thưởng/chức vụ/quà. Khiêm tốn và trang trọng hơn 断る: 受賞を辞退する、出席を辞退する. Đối lập: 受ける／引き受ける／頂戴する.","example":"彼は忙しいことを理由に、受賞を辞退しました。","example_reading":"かれはいそがしいことをりゆうに、じゅしょうをじたいしました。","example_meaning":"Anh ấy lấy lý do bận để xin từ chối nhận giải.","level":"n1"}
],
"grammar": [
{"pattern":"【N5-1】Bản đồ 3 hướng cho–nhận","usage":"Hình dung: 私 (phía tôi) ⇄ 他人 (người ngoài)\n① 私 ──あげる──▶ 他人　(tôi cho đi)\n② 他人 ──くれる──▶ 私　(người ta cho tôi)\n③ 私 ◀──もらう── 他人　(tôi nhận)\n\n▸ ② và ③ là CÙNG MỘT sự việc, chỉ đổi chủ ngữ.\n▸ あげる／くれる: chủ ngữ = NGƯỜI CHO. もらう: chủ ngữ = NGƯỜI NHẬN.\n▸ Chốt: người nhận là 'tôi/phía tôi' → くれる (không bao giờ あげる).","example":"私は田中さんにペンをあげた。\n田中さんが私にペンをくれた。\n私は田中さんにペンをもらった。","example_reading":"わたしはたなかさんにぺんをあげた。\nたなかさんがわたしにぺんをくれた。\nわたしはたなかさんにぺんをもらった。","example_meaning":"Tôi cho anh Tanaka cây bút. (①)\nAnh Tanaka cho tôi cây bút. (②)\nTôi nhận cây bút từ anh Tanaka. (③ = cùng sự việc với ②)"},
{"pattern":"【N5-2】Khung câu của 3 động từ","usage":"▸ あげる:　A(người cho)が ＋ B(người nhận)に ＋ Cを ＋ あげる\n▸ もらう:　B(người nhận)が ＋ A(người cho)に／から ＋ Cを ＋ もらう\n▸ くれる:　A(người cho)が ＋ 私に(thường lược) ＋ Cを ＋ くれる\n\n▸ Nâng/hạ cấp theo quan hệ:\n　やる ／ あげる ／ さしあげる\n　もらう ／ いただく\n　くれる ／ くださる　(xem N3-1)","example":"私は妹に本をあげました。\n私は友達にプレゼントをもらいました。\n友達が（私に）花をくれました。","example_reading":"わたしはいもうとにほんをあげました。\nわたしはともだちにぷれぜんとをもらいました。\nともだちが（わたしに）はなをくれました。","example_meaning":"Tôi đã cho em gái quyển sách.\nTôi đã nhận quà từ bạn.\nBạn đã tặng hoa cho tôi."},
{"pattern":"【N5-3】⭐ Phân biệt trợ từ に／から: quy tắc 'mũi tên'","usage":"Vẽ mũi tên: A ──vật──▶ B   (A = người cho, B = người nhận)\n\n▸ Động từ CHO → đặt に ở ĐẦU mũi tên (người nhận B). KHÔNG đổi được sang から.\n　あげる・やる・さしあげる・くれる・くださる・貸す・教える・渡す・送る・届ける・預ける・返す・贈る\n▸ Động từ NHẬN → đặt に／から ở GỐC mũi tên (người cho A).\n　もらう・いただく・借りる・習う・教わる・預かる・受け取る\n\n▸ から = 'xuất phát từ'. Ưu tiên から khi:\n　① người cho là tổ chức/nơi chốn (会社・役所・図書館)\n　② vật/tin 'gửi đến' (連絡・手紙・荷物)\n　③ muốn nhấn nguồn gốc\n▸ Ở nhóm CHO, từ から chỉ ĐIỂM XUẤT PHÁT, không phải người nhận: 東京から友達に送った.\n▸ Không chồng hai trợ từ: ×誰にからもらった → 誰にもらった／誰からもらった.\n▸ ～てもらう: に là mặc định. から dùng được khi nhận thông tin/vật (教えてもらう・貸してもらう); hành động tay chân (手伝う・運ぶ) chỉ dùng に.","example":"先輩に（から）アドバイスをもらった。\n図書館から本を借りた。\n東京から友達に荷物を送った。\n友達から教えてもらったお店に行った。","example_reading":"せんぱいに（から）あどばいすをもらった。\nとしょかんからほんをかりた。\nとうきょうからともだちににもつをおくった。\nともだちからおしえてもらったおみせにいった。","example_meaning":"Tôi nhận lời khuyên từ đàn anh.\nTôi mượn sách ở thư viện.\nTôi gửi hành lý từ Tokyo cho bạn.\nTôi đã đến quán mà bạn chỉ cho."},
{"pattern":"【N5-4】⭐ Các trợ từ còn lại: は・を・も・で・と","usage":"▸ が／は: chủ ngữ. あげる／くれる → người cho; もらう → người nhận.\n▸ は thay を: đưa VẬT lên làm chủ đề.\n　この本は友達にもらった。(Còn quyển sách này thì tôi nhận từ bạn.)\n▸ に／から ＋ は: đối chiếu hai người nhận/người cho.\n　田中さんにはあげたが、私にはくれなかった。\n▸ も: に／から đứng TRƯỚC も → 兄にもあげた／友達からももらった.\n　Phủ định: 誰にも／何も＋ない、これしか＋ない.\n▸ で: phương tiện hoặc nơi diễn ra (宅配便で送る・会議室で渡す). KHÔNG chỉ người nhận.\n▸ と: 'cùng với', không phải người nhận (友達とお菓子を交換した = đổi với bạn).","example":"このカバンは母にもらいました。\n彼は田中さんにはあげたが、私にはくれなかった。\n誰にもプレゼントをもらいませんでした。","example_reading":"このかばんははにもらいました。\nかれはたなかさんにはあげたが、わたしにはくれなかった。\nだれにもぷれぜんとをもらいませんでした。","example_meaning":"Cái túi này tôi được mẹ cho.\nAnh ấy cho anh Tanaka nhưng không cho tôi.\nTôi không được ai tặng quà cả."},
{"pattern":"【N5-5】ウチ・ソト: 'phía tôi' và ngôi thứ ba","usage":"▸ Người nhận là tôi hoặc phía tôi (gia đình, bạn thân, cùng công ty) → くれる.\n▸ Cả hai đều ngôi thứ ba → người nói đứng về phía người mình đồng cảm hơn.\n▸ Thang gần gũi: 私 > người nhà > bạn thân > người xa lạ.\n▸ Người nhận gần hơn → くれる.  Người cho gần hơn hoặc trung lập → あげる.","example":"友達が弟にお菓子をくれました。\n隣の人が弟にりんごをくれました。\n弟が隣の人にりんごをあげました。","example_reading":"ともだちがおとうとにおかしをくれました。\nとなりのひとがおとうとにりんごをくれました。\nおとうとがとなりのひとにりんごをあげました。","example_meaning":"Bạn cho em trai tôi bánh kẹo. (em tôi thuộc phía tôi)\nNgười hàng xóm cho em tôi quả táo. (người nhận gần hơn)\nEm tôi cho người hàng xóm quả táo. (người cho gần hơn)"},
{"pattern":"【N5-6】Bẫy hay gặp (kiểm tra nhanh)","usage":"① ×友達が私にあげた → ○くれた\n② ×私が友達にくれた → ○あげた\n③ ×友達からあげる／×先生からさしあげる → người nhận luôn là に\n④ ×誰にからもらった → に／から chọn một\n⑤ ×先生が私に本をいただいた → ○くださった (người cho là thầy)","example":"○ 友達が私にプレゼントをくれた。\n× 友達が私にプレゼントをあげた。\n○ 先生が私に本をくださった。\n× 先生が私に本をいただいた。","example_reading":"○ ともだちがわたしにぷれぜんとをくれた。\n× ともだちがわたしにぷれぜんとをあげた。\n○ せんせいがわたしにほんをくださった。\n× せんせいがわたしにほんをいただいた。","example_meaning":"Bạn đã tặng quà cho tôi. (người nhận là tôi → くれる)\n(sai) あげる không dùng khi người nhận là tôi.\nThầy đã cho tôi cuốn sách. (người cho là thầy → くださる)\n(sai) いただく là hướng 'nhận', chủ ngữ phải là người nhận."},
{"pattern":"【N4-1】～てあげる／～てくれる／～てもらう（làm giúp）","usage":"▸ 私が B に V-てあげる　= tôi làm giúp B\n▸ 他人が (私に) V-てくれる　= người ta làm giúp tôi\n▸ 私が 他人に V-てもらう　= tôi được người ta làm giúp (người làm = に)\n\n▸ Hướng và chủ ngữ giữ NGUYÊN như N5-1. Vật bị tác động vẫn đi với を.\n▸ ～てあげる với người trên nghe như ban ơn → dùng お～する (N3-3).","example":"私は友達に宿題を教えてあげた。\n友達が（私に）宿題を教えてくれた。\n私は友達に宿題を教えてもらった。","example_reading":"わたしはともだちにしゅくだいをおしえてあげた。\nともだちが（わたしに）しゅくだいをおしえてくれた。\nわたしはともだちにしゅくだいをおしえてもらった。","example_meaning":"Tôi chỉ bài tập cho bạn.\nBạn chỉ bài tập cho tôi.\nTôi được bạn chỉ bài tập."},
{"pattern":"【N4-2】～てくれる vs ～てもらう: khác ở sắc thái","usage":"▸ ～てくれる: chủ ngữ = người làm. Sắc thái 'họ tự nguyện làm cho mình'.\n▸ ～てもらう: chủ ngữ = người được giúp. Hàm ý mình đã nhờ hoặc mong đợi.\n▸ Phủ định:\n　～てくれなかった = họ không làm (than phiền)\n　～てもらえなかった = mình không được làm giúp","example":"姉に宿題を教えてもらった。\n姉が宿題を教えてくれた。","example_reading":"あねにしゅくだいをおしえてもらった。\nあねがしゅくだいをおしえてくれた。","example_meaning":"Tôi được chị chỉ bài tập. (nhấn: tôi đã nhờ)\nChị đã chỉ bài tập cho tôi. (nhấn: chị tự nguyện)"},
{"pattern":"【N4-3】⭐ Bậc thang nhờ vả: từ thân mật đến văn thư","usage":"① ～て／～てくれ　(rất thân)\n② ～てくれる？／～てもらえる？\n③ ～てくれませんか／～てもらえませんか\n④ ～てくださいませんか／～ていただけませんか\n⑤ ～ていただけないでしょうか\n⑥ お～いただけますでしょうか\n⑦ ～ていただければ幸いです／～賜りますようお願い申し上げます　(văn thư)\n\n▸ Dạng phủ định (～ませんか／～ないでしょうか) làm lời nhờ mềm hơn.\n▸ もらえる／いただける là dạng khả năng. くれる không có dạng khả năng → dùng くださいませんか.\n▸ Mềm hóa phần mở đầu: 恐れ入りますが／お手数ですが／ご多忙のところ.\n▸ Xin vật: ください → もらえませんか → いただけませんか. Thân mật: ちょうだい.","example":"資料を送ってもらえる？\n資料をお送りいただけないでしょうか。\nご確認いただければ幸いです。","example_reading":"しりょうをおくってもらえる？\nしりょうをおおくりいただけないでしょうか。\nごかくにんいただければさいわいです。","example_meaning":"Gửi tài liệu giúp mình được không?\nXin ngài vui lòng gửi tài liệu giúp tôi được không ạ?\nNếu quý vị kiểm tra giúp thì thật là may mắn."},
{"pattern":"【N4-4】やる／～てやる（người dưới, động vật, cây cối）","usage":"▸ やる = あげる khi người nhận là cấp dưới, trẻ nhỏ, động vật, cây cối. Sắc thái bình dân, nam giới.\n▸ Nữ và giới trẻ hay dùng あげる cho dịu hơn (花に水をあげる).\n▸ ～てやる = làm giúp người dưới/động vật.\n▸ Với người ngang hàng trở lên → あげる／～てあげる.","example":"毎朝、犬にえさをやります。\n弟の宿題を見てやりました。","example_reading":"まいあさ、いぬにえさをやります。\nおとうとのしゅくだいをみてやりました。","example_meaning":"Mỗi sáng tôi cho chó ăn.\nTôi đã xem bài tập giúp em trai."},
{"pattern":"【N3-1】Kính ngữ cho–nhận: 3 hướng × 3 cấp độ","usage":"Không đổi hướng, chỉ NÂNG CẤP động từ theo quan hệ trên–dưới, trong–ngoài.\n\n▸ CHO:　　　やる → あげる → さしあげる\n▸ NHẬN:　　 もらう → いただく\n▸ CHO TÔI:　くれる → くださる\n\n▸ さしあげる／いただく = 謙譲語: hạ mình, chỉ hành động của PHÍA MÌNH.\n▸ くださる = 尊敬語: nâng người cho.\n▸ Chia くださる: くださいます／くださいました／くださって (không phải くださります).","example":"友達にあげる → 先生にさしあげる\n友達にもらう → 先生にいただく\n友達がくれる → 先生がくださる","example_reading":"ともだちにあげる → せんせいにさしあげる\nともだちにもらう → せんせいにいただく\nともだちがくれる → せんせいがくださる","example_meaning":"Cho bạn → biếu thầy\nNhận từ bạn → nhận từ thầy\nBạn cho tôi → thầy cho tôi"},
{"pattern":"【N3-2】Nói về người nhà với người ngoài","usage":"▸ Với người ngoài, người nhà thuộc 'phía tôi' nên bị HẠ: dùng 謙譲 (さしあげる／いただく).\n▸ KHÔNG dùng tôn kính くださる cho hành động của người nhà mình.\n▸ Tương tự khi nói về đồng nghiệp công ty mình với khách hàng.\n▸ Ngoại lệ: nếu người CHO là bề trên (thầy, khách) và người nhận là người nhà tôi → vẫn dùng くださる.","example":"母は先生に本をいただきました。\n母が先生にお菓子をさしあげました。\n先生が母に本をくださいました。","example_reading":"はははせんせいにほんをいただきました。\nははがせんせいにおかしをさしあげました。\nせんせいがははにほんをくださいました。","example_meaning":"Mẹ em đã nhận sách từ thầy.\nMẹ em đã biếu thầy bánh.\nThầy đã cho mẹ em quyển sách. (người cho là thầy)"},
{"pattern":"【N3-3】～てさしあげる／～ていただく／～てくださる ＋ お～する","usage":"▸ ～てあげる → ～てさしあげる　(hay tránh, nghe như ban ơn)\n▸ ～てもらう → ～ていただく\n▸ ～てくれる → ～てくださる\n\n▸ Khiêm nhường tự nhiên thay ～てさしあげる: お／ご＋V＋する／いたす\n　お荷物をお持ちします\n▸ Kính tự nhiên: お／ご＋V＋いただく／くださる\n　ご記入いただく／ご説明くださる\n▸ Công thức: お＋Vます(bỏ ます)　／　ご＋danh từ Hán","example":"先生が丁寧に説明してくださいました。\n部長に資料を確認していただきました。\nお荷物をお持ちします。\nご記入いただき、ありがとうございます。","example_reading":"せんせいがていねいにせつめいしてくださいました。\nぶちょうにしりょうをかくにんしていただきました。\nおにもつをおもちします。\nごきにゅういただき、ありがとうございます。","example_meaning":"Thầy đã giải thích tận tình cho em.\nTôi đã nhờ trưởng phòng xem tài liệu giúp.\nĐể tôi xách hành lý giúp quý khách.\nCảm ơn quý khách đã điền thông tin."},
{"pattern":"【N3-4】～させてもらう／～させていただく","usage":"▸ Nấc lịch sự: させてください → させてもらう → させていただく\n▸ Dùng ĐÚNG khi:\n　① cần người nghe cho phép\n　② việc ảnh hưởng đến người nghe (休ませていただきます、拝見させていただきます)\n▸ Dùng GƯỢNG khi chỉ thông báo việc của mình, không cần phép → đổi sang いたします／お～します.\n▸ Phía cho phép: ～させてくれる／～させてあげる／～させてくださる.","example":"今日は早退させていただきます。\n両親は私に好きな道を選ばせてくれました。\n× 私が司会をやらせていただきます。→ ○ 私が司会を務めます。","example_reading":"きょうはそうたいさせていただきます。\nりょうしんはわたしにすきなみちをえらばせてくれました。\n× わたしがしかいをやらせていただきます。→ ○ わたしがしかいをつとめます。","example_meaning":"Hôm nay tôi xin phép về sớm.\nBố mẹ đã để cho tôi chọn con đường mình thích.\nTôi xin làm người dẫn chương trình. (không cần xin phép → nói 務めます tự nhiên hơn)"},
{"pattern":"【N3-5】⭐ Cặp đối lập: 貸す↔借りる, 教える↔習う・教わる, 預ける↔預かる","usage":"Mỗi cặp là cùng một sự việc nhìn từ hai phía.\n\n▸ Động từ CHO (貸す・教える・預ける): người nhận + に\n▸ Động từ NHẬN (借りる・習う・教わる・預かる): người cho + に／から\n\n▸ Ghép ～て: 貸してあげる／貸してくれる／貸してもらう\n▸ 教えてもらう ＝ 教わる ≈ 習う\n▸ 借りる vốn đã là 'nhận' nên ít ghép với もらう／くれる → nói 貸してもらう.","example":"私は友達にノートを貸した。\n友達は私にノートを借りた。\n兄にギターを教わった。\n兄がギターを教えてくれた。","example_reading":"わたしはともだちにのーとをかした。\nともだちはわたしにのーとをかりた。\nあににぎたーをおそわった。\nあにがぎたーをおしえてくれた。","example_meaning":"Tôi cho bạn mượn vở.\nBạn mượn vở của tôi. (cùng sự việc)\nTôi được anh dạy guitar.\nAnh dạy guitar cho tôi. (cùng sự việc)"},
{"pattern":"【N3-6】Biết ơn và đáp lễ: のお礼に／おかげで／恩返し／お世話になる","usage":"▸ [ơn nhận]のお礼に＋[hành động]　= để cảm ơn vì…\n▸ V-てくれた／もらった／くださった＋おかげで＋kết quả tốt　= nhờ ai mà…\n　Nếu kết quả xấu → thành mỉa mai.\n▸ 恩を受ける／恩に着る (mang ơn) → 恩返しをする (đền ơn)\n▸ Aにお世話になる (nhận) ↔ Aのお世話をする (cho)","example":"お世話になったお礼に、先生に花を贈りました。\n先生が丁寧に教えてくださったおかげで、試験に合格できました。\n育ててくれた両親に恩返しがしたいです。","example_reading":"おせわになったおれいに、せんせいにはなをおくりました。\nせんせいがていねいにおしえてくださったおかげで、しけんにごうかくできました。\nそだててくれたりょうしんにおんがえしがしたいです。","example_meaning":"Để cảm ơn vì được giúp đỡ, tôi đã tặng hoa cho thầy.\nNhờ thầy dạy tận tình mà em đã đỗ kỳ thi.\nTôi muốn đền ơn cha mẹ đã nuôi nấng mình."},
{"pattern":"【N2-1】Sắc thái cảm xúc: ban ơn, bất mãn, mỉa mai","usage":"▸ ～てあげたのに／～てやったのに = 'đã làm giúp mà…' (bất mãn, nghe như kể công)\n▸ ～てくれたのに／～てもらったのに = 'người ta đã làm giúp mà tôi lại…' (hối tiếc)\n▸ ～てくれる mỉa mai: よくも言ってくれたね\n▸ Phủ định ～てくれない／～てくれなかった = than phiền\n▸ Cẩn trọng: ～てあげる với người ngoài/trên nghe như ban ơn.","example":"せっかく教えてあげたのに、全然聞いてくれなかった。\n彼は何も手伝ってくれなかった。\nよくもそんなことを言ってくれたね。","example_reading":"せっかくおしえてあげたのに、ぜんぜんきいてくれなかった。\nかれはなにもてつだってくれなかった。\nよくもそんなことをいってくれたね。","example_meaning":"Đã cất công chỉ cho rồi mà họ chẳng nghe gì cả.\nAnh ta chẳng giúp gì cho tôi cả.\nAnh còn dám nói với tôi những lời như vậy à. (mỉa mai)"},
{"pattern":"【N2-2】⭐ Việc gây phiền: bị động 迷惑受身 ≠ ～てもらう／くれる","usage":"▸ ～てもらう／～てくれる luôn mang nghĩa ƠN HUỆ.\n▸ Người khác làm điều gây phiền/hại cho mình → thể bị động: 雨に降られた／足を踏まれた／子どもに泣かれた.\n▸ Câu hỏi kiểm tra: 'Mình có biết ơn không?'\n　Có → ～てもらう／～てくれる\n　Không (khó chịu) → bị động","example":"昨日、電車で隣の人に足を踏まれました。\n友達に来てもらって、助かりました。","example_reading":"きのう、でんしゃでとなりのひとにあしをふまれました。\nともだちにきてもらって、たすかりました。","example_meaning":"Hôm qua trên tàu tôi bị người bên cạnh giẫm vào chân. (phiền)\nNhờ bạn đến giúp mà tôi đỡ quá. (ơn huệ)"},
{"pattern":"【N2-3】⭐ Phân biệt 'người nhận' kiểu trang trọng: に／へ／宛て／向け／への／に対して","usage":"▸ に: người nhận cụ thể (友達にあげる)\n▸ へ: hướng gửi tới, trong thư từ/văn bản (関係者へお送りください)\n▸ に対して: 'đối với', trang trọng (顧客に対して無料で提供する)\n▸ N宛て: ghi người nhận cụ thể trên thư, bưu kiện (母宛ての手紙)\n▸ N向け: nhắm tới NHÓM đối tượng (子ども向けの本)\n▸ Nへの＋N: tình cảm/hành động hướng tới N (母への感謝)\n▸ Nのために: vì lợi ích của N (家族のために働く)\n\nNhớ nhanh: 宛て = gửi cho AI (tên cụ thể).　向け = dành cho NHÓM NÀO.","example":"母宛ての手紙が届いた。\n子ども向けの絵本を贈った。\n母への感謝を手紙に書いた。","example_reading":"ははあてのてがみがとどいた。\nこどもむけのえほんをおくった。\nははへのかんしゃをてがみにかいた。","example_meaning":"Có thư gửi cho mẹ tới.\nTôi đã tặng quyển truyện tranh dành cho trẻ em.\nTôi đã viết lòng biết ơn mẹ vào thư."},
{"pattern":"【N2-4】Danh từ trừu tượng ＋ もらう／くれる／与える","usage":"▸ もらう／くれる: 元気・勇気・許可・チャンス・アドバイス・連絡・返事・休み\n▸ Nguồn nhận có thể đi với から (先輩の言葉から元気をもらう).\n▸ 与える: 影響・印象・自信・不安・損害 (thường không dùng あげる)\n　影響を与える／印象を与える","example":"先輩の言葉から元気をもらいました。\nこの経験は後輩に良い影響を与えました。","example_reading":"せんぱいのことばからげんきをもらいました。\nこのけいけんはこうはいによいえいきょうをあたえました。","example_meaning":"Tôi được tiếp thêm sức sống nhờ lời của đàn anh.\nTrải nghiệm này đã ảnh hưởng tốt đến đàn em."},
{"pattern":"【N2-5】Nghi thức trao–nhận quà và đáp lễ","usage":"▸ Trao: つまらないものですが／ほんの気持ちですが＋どうぞ\n　(hạ thấp quà cho khiêm tốn, không có nghĩa là quà vô giá trị)\n▸ Nhận: ありがたく頂戴いたします／お気遣いありがとうございます\n▸ Từ chối khéo: お気持ちだけいただきます\n▸ Sau bữa ăn: ごちそうさまでした\n▸ Đáp lễ: お返し／ホワイトデー\n▸ Lời chào cảm ơn lâu dài: いつもお世話になっております","example":"これ、つまらないものですが、どうぞ。\nご丁寧にありがとうございます。ありがたく頂戴いたします。\nせっかくですが、お気持ちだけいただきます。","example_reading":"これ、つまらないものですが、どうぞ。\nごていねいにありがとうございます。ありがたくちょうだいいたします。\nせっかくですが、おきもちだけいただきます。","example_meaning":"Đây là chút quà mọn, xin mời anh/chị.\nCảm ơn sự chu đáo của anh/chị, tôi xin nhận với lòng biết ơn.\nCảm ơn nhưng tôi xin nhận tấm lòng thôi ạ."},
{"pattern":"【N1-1】Thang từ khiêm nhường cao cấp","usage":"▸ NHẬN:　いただく → 頂戴する → 拝受する (văn thư) → 賜る (cực trang trọng)\n▸ MƯỢN:　借りる → お借りする → 拝借する\n▸ TẶNG (phía mình):　あげる → さしあげる → 進呈する (khuyến mãi, quảng cáo)\n\n▸ Chỉ dùng cho hành động của PHÍA MÌNH.\n▸ 賜る hầu như chỉ gặp trong cụm cố định: ご愛顧を賜り／ご指導を賜り.","example":"平素は格別のご愛顧を賜り、厚く御礼申し上げます。\nご案内状を拝受いたしました。\nご来店の方に記念品を進呈いたします。","example_reading":"へいそはかくべつのごあいこをたまわり、あつくおれいもうしあげます。\nごあんないじょうをはいじゅいたしました。\nごらいてんのかたにきねんひんをしんていいたします。","example_meaning":"Xin chân thành cảm ơn quý khách đã luôn ưu ái chiếu cố.\nTôi đã nhận được thư mời.\nChúng tôi xin tặng quà kỷ niệm cho quý khách đến cửa hàng."},
{"pattern":"【N1-2】Ban/trao từ trên xuống: 与える／授ける／授与／寄贈／贈与／譲渡","usage":"▸ 与える: cơ hội・ảnh hưởng・giải thưởng・ấn tượng\n▸ 授ける: tri thức・bí quyết・danh hiệu (phía nhận: 授かる)\n▸ 授与する: bằng cấp・huân chương (nghi lễ)\n▸ 寄贈する: tặng sách/tác phẩm cho tổ chức\n▸ 贈与する: tặng tài sản (pháp lý, thuế)\n▸ 譲渡する: chuyển nhượng quyền・cổ phiếu・đất đai\n\n▸ Chung: văn viết, vị thế trên hoặc nghi thức. KHÔNG dùng cho tặng quà thường ngày.","example":"師は弟子に奥義を授けた。\n大学は彼に名誉博士号を授与した。\n卒業生が母校の図書館に蔵書を寄贈した。\n親から子へ財産を贈与する場合は、贈与税がかかる。","example_reading":"しはでしにおうぎをさずけた。\nだいがくはかれにめいよはかせごうをじゅよした。\nそつぎょうせいがぼこうのとしょかんにぞうしょをきぞうした。\nおやからこへざいさんをぞうよするばあいは、ぞうよぜいがかかる。","example_meaning":"Thầy truyền bí quyết cho đệ tử.\nTrường đại học trao bằng tiến sĩ danh dự cho ông ấy.\nCựu sinh viên tặng sách quý cho thư viện trường cũ.\nKhi cha mẹ tặng tài sản cho con thì phát sinh thuế tặng cho."},
{"pattern":"【N1-3】Nhận kiểu 'được ban': 恵まれる／授かる／賜る","usage":"▸ ～に恵まれる: may mắn có được (người, hoàn cảnh, tài năng) → に = thứ được ban\n　才能・環境・友人・天気に恵まれる\n▸ ～を授かる: được trời/thầy ban cho (con cái, tài năng, bí quyết)\n　子どもを授かる\n▸ ～を賜る: nhận từ bề trên, cực trang trọng\n▸ Điểm chung: dạng 'thụ động nhận ân', người ban thường là trời, thầy, bề trên.","example":"私は素晴らしい先生と仲間に恵まれました。\n結婚して三年目に、ようやく子どもを授かりました。","example_reading":"わたしはすばらしいせんせいとなかまにめぐまれました。\nけっこんしてさんねんめに、ようやくこどもをさずかりました。","example_meaning":"Tôi may mắn có được thầy cô và bạn bè tuyệt vời.\nNăm thứ ba sau cưới, cuối cùng chúng tôi cũng có được một đứa con."},
{"pattern":"【Tổng kết】Tự kiểm tra 8 câu","usage":"① 友達（ ）本を借りた。　　(に／から)\n② 友達（ ）本を貸した。　　(に／から)\n③ 会社（ ）給料をもらった。(に／から)\n④ 友達が私に本を（ ）。\n⑤ 先生に本を（ ）。　　　　(tôi cho thầy)\n⑥ 先生に作文を見て（ ）。　(tôi được thầy xem giúp)\n⑦ 母は先生に本を（ ）。　　(nói với khách, mẹ nhận từ thầy)\n⑧ ×先生に荷物を持ってあげた → ?","example":"① に／から ② に ③ から ④ くれた ⑤ さしあげた ⑥ いただいた ⑦ いただきました ⑧ お持ちした","example_reading":"① に／から ② に ③ から ④ くれた ⑤ さしあげた ⑥ いただいた ⑦ いただきました ⑧ おもちした","example_meaning":"① nhóm NHẬN → に／から. ② nhóm CHO → chỉ に. ③ tổ chức → から. ④ người nhận là tôi → くれる. ⑤ tôi cho bề trên → さしあげる. ⑥ tôi nhận từ bề trên → いただく. ⑦ người nhà hạ → いただく. ⑧ khiêm nhường thay ～てあげる."}
]
};
